CREATE TRIGGER t_ins AFTER INSERT ON items
BEGIN
  INSERT INTO audit_log(action, item_sku, new_qty, changed_at)
  VALUES('insert', NEW.sku, NEW.quantity, '2026-01-16');
END;

CREATE TRIGGER t_del AFTER DELETE ON items
BEGIN
  INSERT INTO audit_log(action, item_sku, old_qty)
  VALUES('delete', OLD.sku, OLD.quantity);
END;
DELETE FROM items WHERE id = 3;

CREATE TRIGGER t_log AFTER UPDATE ON items
BEGIN
  INSERT INTO audit_log(action, item_sku, old_qty, new_qty, changed_at)
  VALUES('update', NEW.sku, OLD.quantity, NEW.quantity, '2026-01-15');
END;
UPDATE items SET quantity = 50 WHERE id = 1;

CREATE TRIGGER t_qty AFTER UPDATE OF quantity ON items
BEGIN
  INSERT INTO audit_log(action) VALUES('qty');
END;
UPDATE items SET price = 60.0 WHERE id = 1;

CREATE TRIGGER t_guard BEFORE UPDATE OF quantity ON items
WHEN OLD.quantity < 10
BEGIN
  INSERT INTO audit_log(action) VALUES('guarded');
END;
UPDATE items SET quantity = 12 WHERE id = 6;
UPDATE items SET quantity = 70 WHERE id = 5;

CREATE TRIGGER t_before BEFORE UPDATE ON items
BEGIN
  INSERT INTO audit_log(action) VALUES('before');
END;
CREATE TRIGGER t_after AFTER UPDATE ON items
BEGIN
  INSERT INTO audit_log(action) VALUES('after');
END;
UPDATE items SET quantity = 9 WHERE id = 2;
SELECT action FROM audit_log ORDER BY id;
